(()=>{'use strict';const root=document.querySelector('#M01-lab');if(!root)return;const zh=document.documentElement.lang.startsWith('zh'),d=[300,420,500,620,350,560,710,480];let s={capacity:500,shortageCost:3,day:0};const q=id=>root.querySelector('#M01-'+id);const loss=(cap,x)=>s.shortageCost*Math.max(x-cap,0)+Math.max(cap-x,0);const total=cap=>d.reduce((a,x)=>a+loss(cap,x),0);const text=(x,y,t,anchor='middle',color='#183845')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-family="Arial,Microsoft YaHei,sans-serif" font-size="14">${t}</text>`;const line=(x1,y1,x2,y2,color='#b9c9ce',dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="1.5" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;function result(){let best=200;for(let cap=210;cap<=800;cap+=10)if(total(cap)<total(best))best=cap;return {...s,total:total(s.capacity),selectedDemand:d[s.day],selectedLoss:loss(s.capacity,d[s.day]),bestCapacity:best,bestCost:total(best)}}function draw(){q('cap').value=s.capacity;q('cost').value=s.shortageCost;q('day').value=s.day;const r=result();q('account').textContent=zh?`容量 ${s.capacity} 次；短缺成本 ${s.shortageCost}/次；八天总成本 ${r.total}；第 ${s.day+1} 天需求 ${r.selectedDemand}，损失 ${r.selectedLoss}。网格中首个最低成本容量 ${r.bestCapacity} 次（总成本 ${r.bestCost}）。`:`Capacity ${s.capacity}; shortage cost ${s.shortageCost}/rental; eight-day total ${r.total}; day ${s.day+1}: demand ${r.selectedDemand}, loss ${r.selectedLoss}. First minimum on the grid: capacity ${r.bestCapacity}, total cost ${r.bestCost}.`;let a='';const Y=v=>265-v/800*210;for(let v=0;v<=800;v+=200)a+=line(65,Y(v),800,Y(v))+text(53,Y(v)+5,v,'end');for(let i=0;i<8;i++){const x=100+i*87;a+=`<rect x="${x}" y="${Y(d[i])}" width="45" height="${265-Y(d[i])}" fill="${i===s.day?'#ca8446':'#167b82'}"/>`+text(x+22,289,i+1)+text(x+22,Y(d[i])-8,d[i]);}a+=line(65,Y(s.capacity),800,Y(s.capacity),'#9f4b37','7 5')+text(65,25,zh?'需求与容量（次/日）':'Demand and capacity (rentals/day)','start')+text(800,310,zh?'教学日编号':'Teaching day','end');q('demand').innerHTML=a;const vals=Array.from({length:61},(_,i)=>[200+i*10,total(200+i*10)]),max=Math.max(...vals.map(v=>v[1]))*1.08,X=v=>65+(v-200)/600*735,LY=v=>265-v/max*210;let b='';for(let i=0;i<=4;i++){const v=Math.round(max*i/4);b+=line(65,LY(v),800,LY(v))+text(53,LY(v)+5,v,'end')}for(let v=200;v<=800;v+=100)b+=text(X(v),289,v);b+=`<path d="${vals.map((v,i)=>(i?'L':'M')+X(v[0])+','+LY(v[1])).join(' ')}" fill="none" stroke="#167b82" stroke-width="3"/><circle cx="${X(s.capacity)}" cy="${LY(r.total)}" r="7" fill="#ca8446"/>`+text(65,25,zh?'八天总成本（教学成本单位）':'Eight-day total (illustrative cost units)','start')+text(800,310,zh?'每日容量（次）':'Daily capacity (rentals)','end');q('loss').innerHTML=b;}function set(v){if(v.capacity!==undefined)s.capacity=Math.max(200,Math.min(800,Math.round(Number(v.capacity)/10)*10));if(v.shortageCost!==undefined)s.shortageCost=Math.max(1,Math.min(6,Math.round(Number(v.shortageCost))));if(v.day!==undefined)s.day=Math.max(0,Math.min(7,Math.round(Number(v.day))));draw();return result()}q('cap').oninput=e=>set({capacity:e.target.value});q('cost').oninput=e=>set({shortageCost:e.target.value});q('day').onchange=e=>set({day:e.target.value});const reset=()=>set({capacity:500,shortageCost:3,day:0});q('reset').onclick=reset;window.CourseLab={set,state:result,reset};draw();})();
